    graph = []
    for S in combinations(elements, k):
        for T in combinations(elements, k):
            if len(S & T) == 0:
                graph.append((S, T))
    return graph

def combinations(iterable, r):
    pool = tuple(iterable)
    n = len(pool)
    indices = list(range(r))
    yield tuple(pool[i] for i in indices)
    while True:
        for i in reversed(range(r)):
            if indices[i] != i + n - r:
                break
        else:
            return
        indices[i] += 1
        for j in range(i + 1, r):
            indices[j] = indices[j - 1] + 1
        yield tuple(pool[i] for i in indices)

def tseitin_formula(graph):
    literals = {}
    clauses = []
    literal_id = 0

    def get_literal(S):
        if S not in literals:
            literals[S] = literal_id
            literal_id += 1
        return literals[S]

    for (S, T) in graph:
        x = get_literal(S)
        y = get_literal(T)
        clauses.append([-x, -y])
        clauses.append([x, y])

    # Add unit clause for each vertex
    for S in literals:
        clauses.append([get_literal(S)])

    return clauses

def dpll(clauses):
    def solve(model):
        if not clauses:
            return model
        literal = next((lit for lit in range(1, max(literals.values()) + 1) if lit not in model and -lit not in model), None)
        if literal is None:
            return None

        new_model = model.copy()
        new_model[literal] = True
        result = solve(new_model)
        if result is not None:
            return result

        new_model[literal] = False
        result = solve(new_model)
        if result is not None:
